def overlap_metrics(prediction,truth):
    if prediction.shape!=truth.shape:raise ValueError('掩码形状错配')
    p=prediction.astype(bool);y=truth.astype(bool);inter=(p&y).sum();union=(p|y).sum();total=p.sum()+y.sum()
