# 自编依赖图：只核对图结构，不代替真实能力诊断
prerequisites={'learning_rate':['gradient','loss_scale'],'gradient':['derivative'],
               'derivative':['function'],'interval':['sampling_unit','variance'],
               'variance':['mean'],'tensor_shape':['matrix_shape','broadcasting'],
